def largest_nesting_set(nums):
    seen, best = set(), 0
    for start in range(len(nums)):
        if start in seen:
            continue
        length, value = 0, start
        while value not in seen:
            seen.add(value)
            length += 1
            value = nums[value]
        best = max(best, length)
    return best

